const f={polls:{},notifications:[],channelUnread:{},xp:null,admins:[],adminPassword:'',admin:false,pins:[],peerReadAt:0,voiceRooms:{},activeVoice:'',modal:null,gameTicket:0,record:null,notificationIds:new Set(),suppressedRead:false};
const statusLabel=s=>({online:'Disponible',idle:'Absent',dnd:'Ne pas déranger',invisible:'Invisible',offline:'Hors ligne'}[s]||'Disponible');
function ack(event,payload){return new Promise((resolve,reject)=>socket.timeout(10000).emit(event,payload,(error,r)=>error?reject(Error('Le serveur ne répond pas. Réessaie.')):r?.success?resolve(r):reject(Error(r?.message||'Action refusée.'))));}
function show(title,html,type=''){f.modal=type;$('feature-title').textContent=title;$('feature-body').innerHTML=html;if(!$('feature-dialog').open)$('feature-dialog').showModal();}
function close(){ $('feature-dialog').close(); }
function button(text,attr='',klass=''){return `<button ${attr} class="${klass}">${text}</button>`;}
function contextPayload(){return state.view==='dms'&&state.peer?{to:state.peer}:{channel:state.channel};}
function command(action,m,extra={}){return ack('message_action',{...contextPayload(),id:m.id,action,...extra});}
function findMessage(id){return state.messages.find(m=>String(m.id)===String(id));}
function jump(id){const row=[...document.querySelectorAll('.message[data-id]')].find(n=>n.dataset.id===String(id));if(row){row.scrollIntoView?.({block:'center',behavior:preferences.motion?'instant':'smooth'});row.classList.add('jump-highlight');setTimeout(()=>row.classList.remove('jump-highlight'),2200);}else toast('Ce message ne se trouve plus dans l’historique récent.');}
async function copy(text){try{await navigator.clipboard.writeText(text);toast('Copié.');}catch{show('Copier',`<textarea readonly rows="4">${esc(text)}</textarea><p>Sélectionne le texte puis copie-le.</p>`);}}
function pop(anchor,html){const menu=$('feature-menu');menu.innerHTML=html;menu.hidden=false;const r=anchor?.getBoundingClientRect?.()||{left:20,bottom:80};menu.style.left=Math.max(10,Math.min(r.left,innerWidth-menu.offsetWidth-10))+'px';menu.style.top=Math.max(10,Math.min(r.bottom+6,innerHeight-menu.offsetHeight-12))+'px';}
function hideMenu(){$('feature-menu').hidden=true;$('attach-button').setAttribute('aria-expanded','false');}
function applyTheme(){const name=themes[preferences.theme]?preferences.theme:'default';const t=themes[name];const c=name==='custom'?(preferences.colors||{}):{};const colors=[c.bg||t[1],c.panel||t[2],c.rail||t[3],c.accent||t[4],c.text||t[5]];
 const valid=x=>/^#[\da-f]{6}$/i.test(x);['--bg','--panel','--rail','--button','--text'].forEach((k,i)=>document.body.style.setProperty(k,valid(colors[i])?colors[i]:t[i+1]));
 const light=['light','pink-light'].includes(name);document.body.dataset.theme=name;document.body.classList.toggle('light',light);document.body.style.setProperty('--accent',light?t[4]:`color-mix(in srgb, ${colors[3]} 58%, white)`);document.body.style.setProperty('--hover',`color-mix(in srgb, ${colors[1]} 87%, ${light?'black':'white'})`);document.body.style.setProperty('--border',`color-mix(in srgb, ${colors[1]} 83%, ${light?'black':'white'})`);document.body.style.setProperty('--muted',light?'#657083':'#9da8bc');document.querySelector('meta[name="theme-color"]').content=colors[1];
}
function settings(tab,panel){if(tab==='appearance'){
 panel.innerHTML=`<h3>Toutes les ambiances, dès maintenant</h3><p>Les niveaux n’imposent aucune restriction.</p><div class="theme-grid">${Object.entries(themes).map(([id,t])=>button(`<span class="theme-swatch" style="background:linear-gradient(120deg,${t[3]} 30%,${t[1]} 30%,${t[1]} 70%,${t[4]} 70%)"></span>${t[0]}`,`data-theme-choice="${id}"`,`theme-card ${preferences.theme===id?'active':''}`)).join('')}</div>${preferences.theme==='custom'?`<div class="custom-colors">${[['bg','Fond'],['panel','Panneaux'],['rail','Barre latérale'],['accent','Accent'],['text','Texte']].map(([id,label])=>`<label>${label}<input type="color" data-theme-color="${id}" value="${esc(preferences.colors?.[id]||themes.custom[{bg:1,panel:2,rail:3,accent:4,text:5}[id]])}"></label>`).join('')}</div>`:''}${[['compact','Messages compacts'],['motion','Réduire les animations'],['quietEvents','Masquer les événements automatiques']].map(([id,label])=>`<div class="setting-row"><label>${label}</label><input type="checkbox" data-pref="${id}" ${preferences[id]?'checked':''}></div>`).join('')}<div class="setting-row"><label>Effet de mon pseudo</label><select id="name-effect"><option value="none">Aucun</option><option value="name_glow">Halo</option><option value="name_gradient">Dégradé</option><option value="name_neon">Néon</option></select></div>`;if($('name-effect'))$('name-effect').value=f.xp?.activeNameEffect||'none';return true;
 }if(tab==='notifications'){panel.innerHTML=`<h3>Notifications</h3><p>Les messages privés et mentions sont signalés quand tu ne regardes pas la conversation. Le mode « Ne pas déranger » coupe les alertes.</p>${[['notificationSound','Sons des messages et notifications'],['interfaceSounds','Sons des actions et de la navigation'],['typingSounds','Sons du clavier dans les messages'],['voiceSounds','Sons du vocal et du micro'],['soundboard','Entendre la soundboard du salon']].map(([id,label])=>`<div class="setting-row"><label>${label}</label><input type="checkbox" data-pref="${id}" ${preferences[id]?'checked':''}></div>`).join('')}<button type="button" data-sound-library>Écouter les sons du projet</button><button id="enable-notifications" class="primary">Activer les notifications du navigateur</button><p id="notification-permission" class="section-note">${'Notification' in window?'Autorisation : '+Notification.permission:'Ce navigateur ne propose pas les notifications.'}</p>`;return true;}return false;}
function refreshSelf(){const me=state.users.find(u=>keyName(u.username)===keyName(state.me?.username));if(!me)return;const avatar=$('self-avatar');avatar.innerHTML=safePath(me.avatar)?`<img src="${esc(safePath(me.avatar))}" alt="">`:esc(me.username.slice(0,2).toUpperCase());$('self-status').textContent=statusLabel(me.status);}
renderMembers=function(){const visible=state.users.filter(u=>u.status!=='invisible'||keyName(u.username)===keyName(state.me?.username));$('members').innerHTML=`<h3>Membres connectés — ${visible.length}</h3>`+visible.map(u=>`<button class="person" data-profile="${esc(u.username)}">${avatarHTML(u.username,u.avatar)}<div><strong class="${esc(['name_glow','name_gradient','name_neon'].includes(u.nameEffect)?u.nameEffect:'')}">${esc(u.username)}${keyName(u.username)===keyName(state.me?.username)?' <small>(toi)</small>':''}</strong><small>${esc(u.customStatus||statusLabel(u.status))} · Niv. ${u.level||0}</small></div><span class="online-dot ${esc(u.status)}"></span></button>`).join('');refreshSelf();};
function notificationsBadge(){const count=Object.values(state.unread).reduce((a,b)=>a+Number(b||0),0)+(state.friends.requests?.length||0);for(const el of document.querySelectorAll('[data-view="dms"]')){el.querySelector('.icon-count')?.remove();if(count)el.insertAdjacentHTML('beforeend',`<span class="icon-count">${count>99?'99+':count}</span>`);}const countBell=f.notifications.filter(n=>!n.read).length;const bell=$('notifications-button');bell.querySelector('.icon-count')?.remove();if(countBell)bell.insertAdjacentHTML('beforeend',`<span class="icon-count">${countBell}</span>`);document.title=count?`(${count}) DocSpace`:'DocSpace · 3.5.1';}
function notifyMessage(m,dm=false){if(keyName(m.from||m.username)===keyName(state.me?.username)||f.notificationIds.has(m.id))return;f.notificationIds.add(m.id);if(f.notificationIds.size>400)f.notificationIds.delete(f.notificationIds.values().next().value);
 const focused=!document.hidden&&document.hasFocus();const active=dm?state.view==='dms'&&keyName(state.peer)===keyName(m.from):state.view==='channels'&&state.channel===m.channel;if(focused&&active)return;
 if(!dm){f.channelUnread[m.channel]=(f.channelUnread[m.channel]||0)+1;updateChannelBadges();if(!window.DocSpaceSocial?.mentions(m.content,state.me?.username)){window.DocSpaceSounds?.play('msg_receive','notifications');return;}}
 const n={id:m.id,from:m.from||m.username,body:decodeLegacy(m.content)|| (m.pollId?'Sondage':m.attachment?.isVoiceClip?'Message vocal':'Pièce jointe'),peer:dm?m.from:null,channel:m.channel,read:false};f.notifications.unshift(n);f.notifications=f.notifications.slice(0,50);notificationsBadge();
 if(state.users.find(u=>keyName(u.username)===keyName(state.me?.username))?.status==='dnd')return;
 window.DocSpaceSounds?.play('msg_mention_dm','notifications');
 if(!focused&&preferences.desktopNotifications&&'Notification' in window&&Notification.permission==='granted'){const notification=new Notification(dm?`Message de ${n.from}`:`${n.from} t’a mentionné`,{body:n.body.slice(0,120),icon:'/icon-192.png',tag:String(m.id)});notification.onclick=()=>{window.focus();navigate(dm?'dms':'channels',n.peer,n.channel||state.channel);notification.close();};}
}
function updateChannelBadges(){document.querySelectorAll('[data-channel]').forEach(b=>{b.querySelector('.channel-badge')?.remove();const count=f.channelUnread[b.dataset.channel];if(count)b.insertAdjacentHTML('beforeend',`<span class="pill channel-badge">${count}</span>`);});}
const originalNav=renderNavigation;renderNavigation=function(){originalNav();if(state.view!=='dms'){$('nav-list').insertAdjacentHTML('beforeend',`<button class="nav-item" data-view="arcade">${icon('game')}<span>Arcade DocSpace</span></button>`);renderVoiceMembers();}updateChannelBadges();notificationsBadge();};
function openEmoji(target=null){state.reactionTarget=null;f.emojiTarget=target;const dialog=$('emoji-dialog');if(!dialog.querySelector('#emoji-search')){dialog.querySelector('h2').textContent='Émojis';dialog.querySelector('header').insertAdjacentHTML('afterend',`<input id="emoji-search" placeholder="Rechercher : cœur, chat, rire…" aria-label="Rechercher un emoji"><nav class="emoji-categories" aria-label="Catégories d’émojis">${button('Tous','data-emoji-category="all"')}${emojiGroups.map((g,i)=>button(g[0],`data-emoji-category="${i}" title="${g[1]}"`)).join('')}${button('✦','data-emoji-category="custom" title="Émojis du serveur"')}</nav>`);$('emoji-search').oninput=()=>renderEmojis();}f.emojiCategory='all';$('emoji-search').value='';renderEmojis();dialog.showModal();$('emoji-search').focus();}
function renderEmojis(){const q=$('emoji-search').value.toLowerCase().normalize('NFD').replace(/[\u0300-\u036f]/g,'');let html='';emojiGroups.forEach((g,i)=>{if(f.emojiCategory!=='all'&&String(i)!==f.emojiCategory)return;const label=g[1].normalize('NFD').replace(/[\u0300-\u036f]/g,'');const items=g[2].split(' ').filter(e=>!q||label.includes(q)||e.includes(q));if(items.length)html+=`<span class="emoji-group-title">${g[1].split(' ').slice(0,2).join(' ')}</span>`+items.map(e=>button(e,`data-pick-emoji="${esc(e)}" aria-label="${esc(e)}"`)).join('');});if(['all','custom'].includes(f.emojiCategory)){const custom=state.emojis.filter(e=>!q||e.name.includes(q));if(custom.length)html+='<span class="emoji-group-title">Émojis du serveur</span>'+custom.map(e=>button(`<img class="custom-emoji" src="${esc(safePath(e.url))}" alt="${esc(e.name)}">`,`data-pick-emoji=":${esc(e.name)}:" title="${esc(e.name)}"`)).join('');}$('emoji-grid').innerHTML=html||'<p>Aucun emoji trouvé.</p>';document.querySelectorAll('[data-emoji-category]').forEach(b=>b.classList.toggle('active',b.dataset.emojiCategory===f.emojiCategory));}
function decorateMessage(row,m){const actions=row.querySelector('.message-actions');if(actions){actions.replaceChildren();for(const [symbol,action,title] of [['☺','react','Ajouter une réaction'],['↩','reply','Répondre'],['•••','menu','Actions du message']]){const b=document.createElement('button');b.textContent=symbol;b.title=title;b.setAttribute('aria-label',title);b.dataset.messageTool=action;b.dataset.messageId=m.id;actions.append(b);}}
 if(m.from){const reactions=document.createElement('div');reactions.className='reaction-chips';for(const [emoji,names] of Object.entries(m.reactions||{})){if(!names.length)continue;const b=document.createElement('button');b.innerHTML=textContentHTML(emoji)+' '+names.length;b.classList.toggle('selected',names.includes(state.me?.username));b.title=names.join(', ');b.onclick=()=>command('react',m,{emoji}).catch(e=>toast(e.message));reactions.append(b);}row.querySelector('.message-body')?.append(reactions);if(keyName(m.from)===keyName(state.me?.username)){const receipt=document.createElement('small');receipt.className='receipt';receipt.textContent=new Date(m.timestamp).getTime()<=f.peerReadAt?'Lu':'Envoyé';row.querySelector('.message-body')?.append(receipt);}}
 const poll=row.querySelector('[data-poll]');if(poll)fillPoll(poll);
 if(m.pinned)row.querySelector('.message-body')?.insertAdjacentHTML('afterbegin','<small>📌 Épinglé</small>');
 const content=row.querySelector('.message-content');if(content){const url=String(m.content||'').trim();const gifs=url.split(/\s+/).filter(isGifURL).slice(0,4);if(gifs.length){let caption=url;for(const g of gifs)caption=caption.replace(g,'');content.innerHTML=textContentHTML(m.from?caption:decodeLegacy(caption))+gifs.map(g=>`<a href="${esc(g)}" target="_blank" rel="noopener"><img src="${esc(g)}" loading="lazy" class="attachment-image" alt="GIF partagé"></a>`).join('');}}
}
function isGifURL(url){if(/^\/gifs\/[a-z0-9-]+\.gif$/.test(url)||(/^\/uploads\/[A-Za-z0-9_.-]+\.gif$/i.test(url)&&!url.includes('..')))return true;try{const u=new URL(url);return u.protocol==='https:'&&(/^(media\d*\.giphy\.com|media\.tenor\.com|i\.giphy\.com)$/.test(u.hostname))&&/\.(gif|webp)(?:$|\?)/i.test(u.pathname+u.search);}catch{return false;}}
function menuMessage(m,anchor){const own=keyName(m.from||m.username)===keyName(state.me?.username);f.contextId=m.id;pop(anchor,`<div class="quick-reactions">${['👍','😂','❤️','🔥'].map(e=>button(e,`data-quick-emoji="${e}"`)).join('')}</div>${button('☺ Ajouter une réaction','data-msg-action="react"')}${own?button('✎ Modifier le message','data-msg-action="edit"'):''}${button('↩ Répondre','data-msg-action="reply"')}${button('➜ Transférer','data-msg-action="forward"')}<div class="menu-divider"></div>${button('▣ Copier le texte','data-msg-action="copy"')}${button('📌 '+(m.pinned?'Désépingler':'Épingler'),'data-msg-action="pin"')}${button('◌ Marquer comme non lu','data-msg-action="unread"')}${button('🔗 Copier le lien','data-msg-action="link"')}${button('▣ Copier l’identifiant','data-msg-action="id"')}${own||f.admin&&!m.from?'<div class="menu-divider"></div>'+button('Supprimer le message','data-msg-action="delete"','danger'):''}`);}
async function messageAction(action,m){if(!m)return;hideMenu();if(action==='menu')return;
 if(action==='react'){openEmoji(m);return;}if(action==='reply'){state.reply={id:m.id,username:m.from||m.username,content:m.content||'Pièce jointe'};$('reply-preview').hidden=false;$('reply-preview').innerHTML=`Répondre à ${esc(state.reply.username)}<button id="cancel-reply" aria-label="Annuler">×</button>`;$('message-input').focus();return;}
 if(action==='copy'||action==='id')return copy(action==='id'?String(m.id):decodeLegacy(m.content));
 if(action==='link'){const u=new URL(location.origin);u.hash=new URLSearchParams({view:m.from?'dms':'channels',target:state.peer||state.channel,message:String(m.id)}).toString();return copy(u.href);}
 if(action==='unread'){if(m.from){await ack('mark_dm_unread',{to:state.peer,id:m.id});f.suppressedRead=true;navigate('dms');}else{f.channelUnread[state.channel]=1;navigate('dms');}notificationsBadge();return;}
 if(action==='pin')return command('pin',m).then(()=>toast('Épingle mise à jour.'));
 if(action==='edit'){show('Modifier le message',`<form id="edit-message-form"><label>Message<textarea name="content" required maxlength="${m.from?4000:500}" rows="4">${esc(decodeLegacy(m.content))}</textarea></label><button class="primary">Enregistrer</button></form>`,'edit');f.contextId=m.id;return;}
 if(action==='delete'){show('Supprimer ce message ?',`<p>Cette suppression sera visible par les participants à la conversation.</p><div class="dialog-actions">${button('Annuler','data-close-feature')}${button('Supprimer','id="confirm-message-delete"','danger')}</div>`,'delete');f.contextId=m.id;return;}
 if(action==='forward'){show('Transférer un message',`<form id="forward-form"><label>Destination<select name="destination">${state.channels.map(c=>`<option value="channel:${esc(c.name)}"># ${esc(c.name)}</option>`).join('')}${state.conversations.map(c=>`<option value="dm:${esc(c.username)}">@ ${esc(c.username)}</option>`).join('')}</select></label><p>Le texte et la pièce jointe seront copiés vers la destination choisie.</p><button class="primary">Transférer</button></form>`,'forward');f.contextId=m.id;}
}
function fillPoll(el){const p=f.polls[el.dataset.poll];if(!p)return;const total=p.options.reduce((n,o)=>n+o.votes,0);el.innerHTML=`<small>SONDAGE · ${esc(p.creator)}</small><h4>${esc(p.question)}</h4>${p.options.map((o,i)=>button(`<span>${p.vote===i?'✓ ':''}${esc(o.text)}</span><span>${total?Math.round(o.votes/total*100):0}% · ${o.votes}</span>`,`data-vote-poll="${p.id}" data-option="${i}" style="--vote-width:${total?o.votes/total*100:0}%" ${p.closed?'disabled':''}`,`poll-option ${p.vote===i?'voted':''}`)).join('')}<footer><small>${total} vote${total>1?'s':''} · ${p.closed?'Terminé':'Tu peux changer ton vote'}</small>${!p.closed&&keyName(p.creator)===keyName(state.me?.username)?button('Terminer',`data-close-poll="${p.id}"`):''}</footer>`;}
function pollForm(){show('Créer un sondage',`<form id="poll-form"><label>Question<input name="question" required minlength="3" maxlength="200" placeholder="On fait quoi ce soir ?"></label><div id="poll-options">${[1,2].map(i=>`<label>Réponse ${i}<input name="option" maxlength="100" required placeholder="Option ${i}"></label>`).join('')}</div>${button('+ Ajouter une réponse','type="button" id="add-poll-option"')}<small>Entre 2 et 8 réponses. Les votes sont visibles uniquement dans cette conversation.</small><button class="primary">Publier le sondage</button></form>`,'poll');}
async function queueFile(file){if(!file)return;if(state.uploading)return toast('Un fichier est déjà en cours d’envoi.');const target=draftKey();state.uploading=true;try{toast('Envoi du fichier…');const a=await upload(file);if(target!==draftKey())return toast('Le fichier est envoyé, mais la conversation a changé. Sélectionne-le à nouveau dans la bonne conversation.');state.attachment=a;renderAttachment();toast('Fichier prêt. Ajoute du texte ou envoie-le.');}catch(e){toast(e.message);}finally{state.uploading=false;}}
const originalAttachment=renderAttachment;renderAttachment=function(){originalAttachment();if(state.attachment){const a=state.attachment;if(/\.(png|jpe?g|gif|webp|avif)$/i.test(a.path))$('attachment-preview').insertAdjacentHTML('afterbegin',`<img class="image-preview" src="${esc(safePath(a.path))}" alt="Aperçu de l’image">`);if(a.isVoiceClip)$('attachment-preview').insertAdjacentHTML('afterbegin',`<audio controls src="${esc(safePath(a.path))}" preload="metadata"></audio>`);}};
function gifDialog(){window.DocSpaceSocial.gifs();}
function stopRecording(discard=false){const r=f.record;if(!r)return;r.discard=discard;r.stopping=true;if(r.recorder?.state==='recording')r.recorder.stop();else cleanupRecording(r);}
function cleanupRecording(r){clearInterval(r.timer);cancelAnimationFrame(r.frame);r.stream?.getTracks().forEach(t=>t.stop());r.context?.close().catch(()=>{});if(f.record===r)f.record=null;}
function recordingDialog(){show('Message vocal',`<p>Enregistre jusqu’à 3 minutes, puis écoute ton message avant de l’envoyer.</p><div class="recording-indicator"><span class="dot" hidden></span><time id="record-time">00:00</time></div><meter id="record-meter" min="0" max="1" value="0" aria-label="Volume du micro"></meter><div id="record-preview"></div><div class="dialog-actions">${button('Enregistrer','id="record-start"','primary')}${button('Arrêter','id="record-stop" hidden')}${button('Joindre au message','id="record-attach" hidden','primary')}</div>`,'record');f.recordFile=null;}
async function startRecording(){if(f.record)return;const r={chunks:[],stream:null,discard:false,target:draftKey()};f.record=r;$('record-start').disabled=true;try{if(!navigator.mediaDevices?.getUserMedia||!window.MediaRecorder)throw Error('L’enregistrement demande un navigateur compatible et HTTPS (ou localhost).');
 r.stream=await navigator.mediaDevices.getUserMedia({audio:{deviceId:preferences.microphone?{exact:preferences.microphone}:undefined,echoCancellation:preferences.echo!==false,noiseSuppression:preferences.noise!==false}});if(r.discard||!$('feature-dialog').open||f.modal!=='record'){cleanupRecording(r);return;}
 const mime=['audio/webm;codecs=opus','audio/ogg;codecs=opus','audio/mp4'].find(t=>MediaRecorder.isTypeSupported(t));r.recorder=new MediaRecorder(r.stream,mime?{mimeType:mime,audioBitsPerSecond:64000}:undefined);r.started=Date.now();
 r.recorder.ondataavailable=e=>{if(e.data.size)r.chunks.push(e.data);};r.recorder.onstop=()=>{const duration=Math.min(180,(Date.now()-r.started)/1000);cleanupRecording(r);if(r.discard||!$('feature-dialog').open||f.modal!=='record')return;const blob=new Blob(r.chunks,{type:r.recorder.mimeType});if(!blob.size)return toast('Aucun son enregistré.');if(blob.size>8*1048576)return toast('Le message dépasse 8 Mo. Enregistre un extrait plus court.');f.recordFile={file:new File([blob],`vocal-${Date.now()}.${blob.type.includes('mp4')?'m4a':blob.type.includes('ogg')?'ogg':'webm'}`,{type:blob.type}),duration,target:r.target};if(f.recordURL)URL.revokeObjectURL(f.recordURL);f.recordURL=URL.createObjectURL(blob);$('record-preview').innerHTML=`<audio controls src="${f.recordURL}"></audio>`;$('record-attach').hidden=false;$('record-start').hidden=false;$('record-start').disabled=false;$('record-start').textContent='Réenregistrer';$('record-stop').hidden=true;document.querySelector('.recording-indicator .dot').hidden=true;};
 r.recorder.onerror=()=>{cleanupRecording(r);toast('Le navigateur a interrompu l’enregistrement.');};r.recorder.start(500);$('record-start').hidden=true;$('record-stop').hidden=false;$('record-attach').hidden=true;$('record-preview').replaceChildren();document.querySelector('.recording-indicator .dot').hidden=false;
 r.timer=setInterval(()=>{const seconds=Math.floor((Date.now()-r.started)/1000);if($('record-time'))$('record-time').textContent=`${String(Math.floor(seconds/60)).padStart(2,'0')}:${String(seconds%60).padStart(2,'0')}`;if(seconds>=180)stopRecording();},200);
 if(window.AudioContext){r.context=new AudioContext();const analyser=r.context.createAnalyser();analyser.fftSize=256;r.context.createMediaStreamSource(r.stream).connect(analyser);const data=new Uint8Array(256);const tick=()=>{if(!f.record||!$('record-meter'))return;analyser.getByteTimeDomainData(data);$('record-meter').value=Math.min(1,Math.sqrt(data.reduce((a,b)=>a+((b-128)/128)**2,0)/256)*4);r.frame=requestAnimationFrame(tick);};tick();}
 }catch(e){cleanupRecording(r);if($('record-start'))$('record-start').disabled=false;toast(e.name==='NotAllowedError'?'Microphone non autorisé. Vérifie les permissions du navigateur.':e.message);}}
const shortcuts=[['🎮','Inviter à jouer','game-invite'],['💬','Messages privés','dms'],['👥','Amis','friends'],['📁','Fichiers & médias','files'],['🟢','Présence','presence'],['🔊','Soundboard','soundboard'],['🏆','Classement XP','leaderboard'],['📊','Statistiques','stats'],['🔗','Copier l’invitation','invite'],['📋','Nouveautés / Patchs','patches'],['🛡','Administration','admin'],['🎨','Thèmes','themes'],['⚙','Paramètres','settings']];
function quickMenu(anchor){pop(anchor,'<div class="menu-label">DOCSPACE · 3.5.1</div><div class="quick-grid">'+shortcuts.map(([i,n,a])=>button(`<span>${i}</span>${n}`,`data-feature="${a}"`)).join('')+'</div><div class="menu-divider"></div><small>Ctrl + K : navigation rapide</small>');}
function showProfile(p){show(p.username,`${avatarHTML(p.username,p.avatar)}<p>${esc(statusLabel(p.status))} · Niveau ${p.level||0}</p><p>${esc(p.bio||'Ce profil n’a pas encore de description.')}</p><p>Membre depuis ${p.joinDate?new Date(p.joinDate).toLocaleDateString('fr-FR'):'les débuts du serveur'}</p>${keyName(p.username)===keyName(state.me?.username)?button('Modifier mon profil','data-feature="settings"','primary'):`<div class="dialog-actions">${friendActionHTML(p.username)}${button('Message privé',`data-profile-dm="${esc(p.username)}"`,'primary')}${button('Inviter à jouer',`data-game-invite-to="${esc(p.username)}"`)}</div>`}`,'profile');}
async function feature(name){hideMenu();if(['dms','friends','files'].includes(name)){close();navigate(name==='friends'?'dms':name);return;}if(name==='settings'||name==='themes'){close();showSettings(name==='themes'?'appearance':'profile');return;}if(name==='invite')return copy(location.origin);
 if(name==='search'){show('Retrouver un message',`<input id="message-search" placeholder="Rechercher dans cette conversation…"><div class="search-results" id="message-search-results"></div><small>Recherche dans les 250 derniers messages chargés.</small>`,'search');$('message-search').focus();renderSearch('');}
 if(name==='quick'){show('Aller à…',`<input id="quick-search" placeholder="Salon, ami ou fonctionnalité…"><div id="quick-results" class="search-results"></div>`,'quick');renderQuick('');$('quick-search').focus();}
 if(name==='notifications'){show('Notifications',`${button('Tout marquer comme lu','id="read-notifications"')}<div class="search-results">${f.notifications.map((n,i)=>button(`<strong>${esc(n.from)}</strong><span>${esc(n.body.slice(0,80))}</span>`,`data-notification="${i}"`,'result-row')).join('')||'<p>Aucune notification pour le moment.</p>'}</div>${button('Régler mes notifications','id="notification-settings"')}`,'notifications');}
 if(name==='presence'){show('Présence',`<div class="search-results" id="presence-results"><p>Chargement…</p></div>`,'presence');socket.emit('get_presence_history');}
 if(name==='leaderboard'){show('Participation au serveur',`<p>Les niveaux reflètent votre participation. Tous les thèmes et effets de pseudo sont déjà accessibles.</p><div class="stat-grid"><div class="stat-box"><strong>${f.xp?.level||0}</strong><small>TON NIVEAU</small></div><div class="stat-box"><strong>${f.xp?.xp||0}</strong><small>TON XP</small></div><div class="stat-box"><strong>${f.xp?.totalMessages||0}</strong><small>MESSAGES</small></div></div><div id="leaderboard-results" class="search-results"></div>`,'leaderboard');socket.emit('get_leaderboard');}
 if(name==='stats')return window.DocSpaceSocial.stats();
 if(name==='patches')return window.DocSpaceSocial.patches();
 if(name==='game-invite')return window.DocSpaceSocial.invite();
 if(name==='soundboard'){show('Soundboard',`<p>Joue un son dans #${esc(state.channel)}. Chaque personne peut couper la soundboard dans ses paramètres.</p><div class="quick-grid">${[['tada','✨ Victoire'],['applause','👏 Bravo'],['rimshot','🥁 Percussion'],['airhorn','📣 Fanfare'],['bruh','😐 Bruh'],['wow','😮 Surprise']].map(([id,n])=>button(n,`data-sound="${id}"`)).join('')}</div>`,'soundboard');}
 if(name==='pins'){const pins=state.view==='dms'?state.messages.filter(m=>m.pinned):f.pins.filter(m=>m.channel===state.channel);show('Messages épinglés',`<div class="search-results">${pins.map(m=>button(`<strong>${esc(m.from||m.username)}</strong><span>${esc(decodeLegacy(m.content)||'Pièce jointe')}</span>`,`data-jump="${esc(m.id)}"`,'result-row')).join('')||'<p>Aucun message épinglé dans cette conversation.</p>'}</div>`,'pins');}
 if(name==='admin')adminPanel();
}
function renderSearch(q){const list=state.messages.filter(m=>!q||keyName(decodeLegacy(m.content)).includes(keyName(q))).slice(-50).reverse();$('message-search-results').innerHTML=list.map(m=>button(`<strong>${esc(m.from||m.username)}</strong><span>${esc(decodeLegacy(m.content).slice(0,150)||'Pièce jointe')}</span>`,`data-jump="${esc(m.id)}"`,'result-row')).join('')||'<p>Aucun résultat.</p>';}
function renderQuick(q){const choices=[...shortcuts.map(([i,n,a])=>({label:i+' '+n,attr:`data-feature="${a}"`})),...state.channels.map(c=>({label:'# '+c.name,attr:`data-quick-channel="${esc(c.name)}"`})),...state.conversations.map(c=>({label:'@ '+c.username,attr:`data-profile-dm="${esc(c.username)}"`}))];$('quick-results').innerHTML=choices.filter(c=>keyName(c.label).includes(keyName(q))).map(c=>button(esc(c.label),c.attr,'result-row')).join('');}
function adminPanel(){if(!f.admin){show('Administration',`<p>Connecte-toi au mode administrateur avec le mot de passe configuré pour ce serveur.</p><form id="admin-login-form"><label>Mot de passe administrateur<input name="password" type="password" required autocomplete="off"></label><button class="primary">Ouvrir l’administration</button></form>`,'admin');return;}
 show('Administration',`<p class="admin-status">Mode administrateur actif · ${esc(state.me.username)}</p><div class="admin-tabs">${button('Modération','data-admin-tab="moderation"')}${button('Salons','data-admin-tab="channels"')}${button('Serveur','data-admin-tab="server"')}${button('Quitter le mode admin','id="admin-logout"')}</div><div id="admin-content"></div>`,'admin');renderAdminTab('moderation');}
function renderAdminTab(tab){const panel=$('admin-content');if(tab==='moderation'){panel.innerHTML=`<form id="admin-moderate-form" class="admin-form"><label>Utilisateur<input name="target" placeholder="Pseudo exact" list="admin-users" required><datalist id="admin-users">${state.users.map(u=>`<option value="${esc(u.username)}">`).join('')}</datalist></label><label>Action<select name="action"><option value="kick">Expulser de la session</option><option value="ban">Bannir</option><option value="unban">Débannir</option><option value="voice_kick">Expulser du vocal</option></select></label><label>Durée du bannissement (minutes, 0 = permanent)<input name="duration" type="number" min="0" max="525600" value="60"></label><button class="danger">Appliquer à cet utilisateur</button></form>`;}if(tab==='channels'){panel.innerHTML=`<form id="admin-channel-form" class="admin-form"><label>Type<select name="type"><option value="create_text">Salon texte</option><option value="create_voice">Salon vocal</option></select></label><label>Nom<input name="name" required maxlength="30"></label><label>Catégorie<input name="category" value="💬 Discussion" maxlength="40"></label><button class="primary">Créer le salon</button></form><div class="search-results">${state.channels.filter(c=>c.name!=='général').map(c=>`<div class="result-row"><span># ${esc(c.name)}</span>${button('Supprimer',`data-delete-channel="${esc(c.name)}"`,'danger')}</div>`).join('')}</div>`;}if(tab==='server'){panel.innerHTML=`<form id="admin-slow-form" class="admin-form"><label>Mode lent : secondes entre les messages<input name="seconds" type="number" min="0" max="300" value="0" required></label><button>Appliquer le délai</button></form><div class="dialog-actions">${button('Activer le silence','data-admin-action="mute_all"')}${button('Réouvrir le chat','data-admin-action="unmute_all"')}</div><form id="admin-announce-form" class="admin-form"><label>Annonce<textarea name="message" required maxlength="500"></textarea></label><button class="primary">Publier dans le serveur</button></form>`;}}
function renderVoiceMembers(){for(const b of document.querySelectorAll('[data-voice-room]')){let list=b.nextElementSibling;if(!list?.classList.contains('voice-users')){list=document.createElement('div');list.className='voice-users';b.after(list);}const users=f.voiceRooms[b.dataset.voiceRoom]||[];list.innerHTML=users.map(u=>`<div class="voice-user ${u.speaking?'speaking':''}">${avatarHTML(u.username,u.avatar)}<span>${esc(u.username)}</span>${u.muted?'⌁':''}${u.deafened?'◌':''}</div>`).join('');b.classList.toggle('voice-connected',f.activeVoice===b.dataset.voiceRoom);}}
function voicePage(room){window.closeDocSpaceGames?.();rememberDraft();state.view='voice';state.peer=null;$('conversation').hidden=true;$('page').hidden=false;$('page').className='voice-page';setPage(room,'Salon vocal','◖');renderNavigation();renderMembers();setDrawer(false);f.displayVoice=room;drawVoicePage();}
function drawVoicePage(){if(state.view==='voice')window.DocSpaceVoice.renderPage(f.displayVoice,f.voiceRooms[f.displayVoice]||[]);}
const originalArcade=renderArcade;renderArcade=function(){originalArcade();const cards=$('page').querySelector('.page-cards');cards.insertAdjacentHTML('beforeend',`<button class="feature-card" data-indie-open><h3>Indie Engine</h3><p>Notes, rythme et univers Undertale / Deltarune.</p><span class="pill">Godot · Rythme · Solo</span></button>`);const ids=['tetris','maze','pong','orbit-garden','indie-engine'];cards.querySelectorAll('.feature-card').forEach((card,i)=>card.insertAdjacentHTML('afterbegin',`<img class="game-cover" src="/covers/${ids[i]}.svg" alt="" loading="lazy">`));};
async function openGodot(game){window.closeDocSpaceGames?.();const ticket=++f.gameTicket;const title=game==='indie-engine'?'Indie Engine · Undertale / Deltarune':'Orbit Garden';$('page').classList.add('game-page');$('page').innerHTML=`<div class="page-heading"><h2>${title}</h2>${button('Retour à l’Arcade','data-view="arcade"')}</div><p>Chargement du jeu…</p>`;try{const r=await fetch(`/games/${game}/index.html`,{method:'HEAD'});if(!r.ok)throw Error('Les fichiers du jeu sont absents.');if(ticket!==f.gameTicket||state.view!=='arcade')return;$('page').innerHTML=`<div class="page-heading"><h2>${title}</h2><div>${button('Plein écran','id="game-fullscreen"')}${button('Retour à l’Arcade','data-view="arcade"')}</div></div><iframe id="godot-frame" title="${title}" src="/games/${game}/index.html" allow="fullscreen; autoplay; gamepad" allowfullscreen></iframe><small class="game-help">${game==='indie-engine'?'Clique dans le jeu pour activer le son · Entrée : valider / pause · Flèches : notes et menus':'Flèches / ZQSD : déplacement · Récolte les huit cristaux'}</small>`;}catch(e){if(ticket===f.gameTicket)$('page').innerHTML=`<div class="empty"><h2>Jeu indisponible</h2><p>${esc(e.message)}</p>${button('Retour à l’Arcade','data-view="arcade"','primary')}</div>`;}}
// Mount controls once; all dynamic content uses delegated listeners.
