$('feature-dialog').addEventListener('close',()=>{stopRecording(true);if(f.recordURL){URL.revokeObjectURL(f.recordURL);f.recordURL=null;}f.modal=null;});
$('feature-dialog').addEventListener('click',e=>{if(e.target===$('feature-dialog')){const r=e.target.getBoundingClientRect();if(e.clientX<r.left||e.clientX>r.right||e.clientY<r.top||e.clientY>r.bottom)close();}});
