$('attach-button').onclick=()=>{if(!$('feature-menu').hidden)return hideMenu();$('attach-button').setAttribute('aria-expanded','true');pop($('attach-button'),`${button('📎 Joindre un fichier','data-attach="file"')}${button('🖼 Image ou screenshot','data-attach="image"')}${button('▤ Créer un sondage','data-attach="poll"')}${button('🎙 Message vocal','data-attach="voice"')}<div class="menu-divider"></div><small>Tu peux aussi coller une image avec Ctrl + V.</small>`);};
